#!/usr/bin/env python3
"""Generate P22's exact P|S union from pinned HF; no input/output fixtures."""
import hashlib
import json
from pathlib import Path
import subprocess
import tokenizers
from tokenizers import Regex, pre_tokenizers

ROOT = Path(__file__).resolve().parents[2]


def main():
    assert tokenizers.__version__ == '0.22.2', tokenizers.__version__
    scalars = ''.join(chr(c) for c in range(0x110000) if not 0xD800 <= c <= 0xDFFF)
    split = pre_tokenizers.Split(Regex(r'[\p{P}\p{S}]+'), 'removed', invert=True)
    ranges = [(ord(s[0]), ord(s[-1])) for s, _ in split.pre_tokenize_str(scalars)]
    lines = ['// Code generated by testdata/patterns/generate_punctuation_tables.py; DO NOT EDIT.',
             '// Unicode P|S membership pinned to tokenizers 0.22.2 native oracle.',
             'package scan', '', 'var punctuationSymbolRanges = [...]runeRange{']
    lines += ['{0x%X, 0x%X},' % r for r in ranges]
    lines += ['}', '']
    table = ROOT / 'internal/scan/punctuation_tables.go'
    table.write_text('\n'.join(lines))
    subprocess.run(['gofmt', '-w', str(table)], check=True)
    path = ROOT / 'testdata/patterns/P22/manifest.json'
    manifest = json.loads(path.read_text())
    digest = lambda p: hashlib.sha256(p.read_bytes()).hexdigest()
    manifest.update(oracle_native_sha256=digest(Path(tokenizers.__file__).parent/'tokenizers.abi3.so'),
                    tables_sha256=digest(table), generator_sha256=digest(Path(__file__)))
    path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2)+'\n')
    print(f'Generated {len(ranges)} P|S ranges from all valid scalars; no stored reference outputs.')


if __name__ == '__main__':
    main()
